set -euo pipefail
python3 - <<'PY'
import zipfile
import shutil
import os
from xml.etree import ElementTree as ET
import openpyxl
from openpyxl.utils import get_column_letter

def percentile_inc(values, k: float):
    xs=sorted(values)
    n=len(xs)
    if n==0:
        return None
    if k<=0:
        return xs[0]
    if k>=1:
        return xs[-1]
    rank = (n-1)*k + 1
    i = int(rank)
    frac = rank - i
    if i<=1:
        return xs[0]
    if i>=n:
        return xs[-1]
    a = xs[i-1]
    b = xs[i]
    return a + frac*(b-a)

def fmt_number(x):
    return format(float(x), '.15g')

xlsx='/root/output/result.xlsx'

# Compute values
wb=openpyxl.load_workbook(xlsx, data_only=False)
ws_task=wb['Task']
ws_data=wb['Data']

years=[ws_task[f'{get_column_letter(c)}10'].value for c in range(8,13)]
header_years=[ws_data[f'{get_column_letter(c)}4'].value for c in range(8,13)]
if years!=header_years:
    raise SystemExit(f'Year headers mismatch Task vs Data: Task={years} Data={header_years}')

series_year_val={}
for r in range(21,39):
    series=ws_data[f'D{r}'].value
    if not series:
        continue
    for idx,c in enumerate(range(8,13)):
        year=header_years[idx]
        v=ws_data[f'{get_column_letter(c)}{r}'].value
        series_year_val[(series, year)] = v

computed={}
lookup_cells=[]
for r1,r2 in [(12,17),(19,24),(26,31)]:
    for r in range(r1,r2+1):
        series=ws_task[f'D{r}'].value
        for idx,c in enumerate(range(8,13)):
            year=years[idx]
            ref=f'{get_column_letter(c)}{r}'
            lookup_cells.append(ref)
            val=series_year_val.get((series, year))
            if val is None:
                raise SystemExit(f'Missing data for {series}/{year} (for {ref})')
            computed[ref]=float(val)

slack_cells=[]
for r in range(35,41):
    fin=r-23
    scrap=r-16
    cap=r-9
    for c in range(8,13):
        col=get_column_letter(c)
        ref=f'{col}{r}'
        slack_cells.append(ref)
        computed[ref]=(computed[f'{col}{fin}'] - computed[f'{col}{scrap}'])/computed[f'{col}{cap}']*100.0

stat_rows=list(range(42,48))
stats_by_row={r: ws_task[f'E{r}'].value for r in stat_rows}

for c in range(8,13):
    col=get_column_letter(c)
    slack_vals=[computed[f'{col}{r}'] for r in range(35,41)]
    xs=sorted(slack_vals)
    for r in stat_rows:
        label=stats_by_row[r]
        ref=f'{col}{r}'
        if label=='Minimum':
            computed[ref]=xs[0]
        elif label=='Maximum':
            computed[ref]=xs[-1]
        elif label=='Median':
            computed[ref]=(xs[2]+xs[3])/2.0
        elif label=='Simple mean':
            computed[ref]=sum(slack_vals)/6.0
        elif label=='25th percentile':
            computed[ref]=percentile_inc(slack_vals,0.25)
        elif label=='75th percentile':
            computed[ref]=percentile_inc(slack_vals,0.75)
        else:
            raise SystemExit(f'Unexpected stat label {label!r} at row {r}')

for c in range(8,13):
    col=get_column_letter(c)
    weights=[computed[f'{col}{r}'] for r in range(26,32)]
    values=[computed[f'{col}{r}'] for r in range(35,41)]
    computed[f'{col}50']=sum(v*w for v,w in zip(values,weights))/sum(weights)

formula_refs=set(lookup_cells)
formula_refs.update(slack_cells)
for r in range(42,48):
    for c in range(8,13):
        formula_refs.add(f'{get_column_letter(c)}{r}')
for c in range(8,13):
    formula_refs.add(f'{get_column_letter(c)}50')

# Determine Task sheet xml path via workbook rels
ns_main='http://schemas.openxmlformats.org/spreadsheetml/2006/main'
ns_docrel='http://schemas.openxmlformats.org/officeDocument/2006/relationships'
ns_pkgrel='http://schemas.openxmlformats.org/package/2006/relationships'

def qn(ns,tag):
    return f'{{{ns}}}{tag}'

with zipfile.ZipFile(xlsx,'r') as z:
    workbook_xml=z.read('xl/workbook.xml')
    rels_xml=z.read('xl/_rels/workbook.xml.rels')

wb_root=ET.fromstring(workbook_xml)
sheet_rid=None
for sh in wb_root.findall(f'.//{qn(ns_main,"sheet")}'):
    if sh.get('name')=='Task':
        sheet_rid=sh.get(f'{{{ns_docrel}}}id')
        break
if not sheet_rid:
    raise SystemExit('Task sheet rid not found')

rels_root=ET.fromstring(rels_xml)
task_sheet_path=None
for rel in rels_root.findall(f'.//{qn(ns_pkgrel,"Relationship")}'):
    if rel.get('Id')==sheet_rid:
        target=rel.get('Target')
        # might be /xl/worksheets/sheet1.xml
        if target.startswith('/'):
            target=target[1:]
        task_sheet_path=target
        break
if not task_sheet_path:
    raise SystemExit(f'Could not map rid {sheet_rid} to target')

print('Task worksheet xml path:', task_sheet_path)

# Patch XML

tmp='/root/output/result_tmp.xlsx'
shutil.copy(xlsx,tmp)

with zipfile.ZipFile(tmp,'r') as zin, zipfile.ZipFile(xlsx,'w',compression=zipfile.ZIP_DEFLATED) as zout:
    for item in zin.infolist():
        data=zin.read(item.filename)
        if item.filename==task_sheet_path:
            root=ET.fromstring(data)
            ET.register_namespace('', ns_main)
            patched=0
            for c_elem in root.findall(f'.//{qn(ns_main,"c")}'):
                ref=c_elem.get('r')
                if ref not in formula_refs:
                    continue
                f_elem=c_elem.find(qn(ns_main,'f'))
                if f_elem is None:
                    continue
                v_elem=c_elem.find(qn(ns_main,'v'))
                if v_elem is None:
                    v_elem=ET.SubElement(c_elem, qn(ns_main,'v'))
                v_elem.text=fmt_number(computed[ref])
                patched += 1
            data=ET.tostring(root, encoding='utf-8', xml_declaration=True)
            print('Patched cached values count:', patched)
        zout.writestr(item, data)

os.remove(tmp)
print('Done patching cached values')
PY
